// Matter bridges engine (matter.js), created when the flow starts and closed when it stops
// libs: matter (@matter/main), devices (@matter/main/devices), endpoints (@matter/main/endpoints),
//       behaviors (@matter/main/behaviors), mtypes (@matter/main/types), dgram
// output 1: DKNR commands (MQTT) / output 2: status changed (refresh of the pages)
//
// A bridge is a Matter node (ServerNode) with its own pairing, port and storage. It holds an
// aggregator endpoint and one bridged endpoint per DKNR device. Bridges are kept by id: only
// the bridge "main" exists today, a device without bridge goes to it.

const BOOL_ON = [true, 1, '1', 'true', 'ON', 'on', 'On'];

// DKNR device types to Matter device types
//   device: Matter device type
//   state: DKNR value to Matter attributes (null if the value is not usable)
//   listen: call order(context, asked) when an attribute changes, returns the function removing the listener
//   command: asked state to DKNR value of an entity (undefined: nothing to send)
const types = {
    'switch': {
        'device': devices.OnOffPlugInUnitDevice,
        'state': (def, value) => {
            if (def.type === 'number') {
                const num = Number.parseFloat(value);

                return isNaN(num) ? null : { 'onOff': { 'onOff': num > 0 } };
            }

            return { 'onOff': { 'onOff': BOOL_ON.includes(value) !== (def.unit === 'rb') } };
        },
        'listen': (endpoint, order) => {
            const handler = (value, old, context) => order(context, { 'onOff': { 'onOff': value === true } });
            endpoint.events.onOff.onOff$Changed.on(handler);

            return () => endpoint.events.onOff.onOff$Changed.off(handler);
        },
        'command': (def, asked, current, cfg) => {
            const on = asked.onOff.onOff;
            if (def.type === 'number') {
                // dimmer: keep its level if already on
                if (on && Number.parseFloat(current) > 0) {

                    return undefined;
                }

                return on ? (cfg.dimmer_on || 99) : 0;
            }

            return on !== (def.unit === 'rb') ? 1 : 0;
        }
    },
    'temperature': {
        'device': devices.TemperatureSensorDevice,
        'state': (def, value) => {
            const num = Number.parseFloat(value);

            // Matter: hundredths of °C
            return isNaN(num) ? null : { 'temperatureMeasurement': { 'measuredValue': Math.round(num * 100) } };
        }
    }
};

const engine = {
    'bridges': {},
    'queue': Promise.resolve(),
    'closed': false
};

const config = () => global.get('describe.matter', 'memoryOnly') || {};
const allDevices = () => global.get('devices', 'default') || {};
const catalog = () => global.get('catalog', 'memoryOnly') || { 'entities': {}, 'values': {} };

// one action at a time
engine.push = function (task) {
    engine.queue = engine.queue.then(task).catch(e => node.error('matter: ' + (e && e.message ? e.message : e)));

    return engine.queue;
};

// devices published by a bridge
function wanted(bridge) {
    const all = allDevices();
    let list = {};
    for (const id in all) {
        const d = all[id];
        if (typeof d === 'object' && d !== null && d.active === true && Array.isArray(d.entities) && d.entities.length > 0
            && typeof types[d.type] === 'object' && (d.bridge || 'main') === bridge.id
        ) {
            list[id] = d;
        }
    }

    return list;
}

// value of an entity: current one, or the last one known before restart (sources not retaining their values)
function valueOf(uid) {
    const values = catalog().values || {};
    if (values[uid] !== undefined) {

        return values[uid];
    }

    return (global.get('last', 'default') || {})[uid];
}

// QR code of a pairing code as a SVG image (matter.js draws it with block characters, two modules per character)
function qrSvg(text) {
    const lines = mtypes.QrCode.get(text).split('\n').filter(l => l.trim() !== '');
    const width = Math.max(...lines.map(l => [...l].length));
    const height = lines.length * 2;
    let path = '';
    lines.forEach((line, row) => {
        const chars = [...line];
        for (let x = 0; x < width; x++) {
            const c = chars[x] || ' ';
            const dark = [c !== '█' && c !== '▀', c !== '█' && c !== '▄'];
            for (let half = 0; half < 2; half++) {
                const y = row * 2 + half;
                // first and last half lines are outside the code
                if (dark[half] && y > 0 && y < height - 1) {
                    path += 'M' + x + ' ' + y + 'h1v1h-1z';
                }
            }
        }
    });

    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="-3 -2 ' + (width + 6) + ' ' + (height + 4) + '" shape-rendering="crispEdges">'
        + '<rect x="-3" y="-2" width="' + (width + 6) + '" height="' + (height + 4) + '" fill="#ffffff"/>'
        + '<path fill="#000000" d="' + path + '"/></svg>';
}

// status of the bridges for the pages (plain data)
function publish() {
    let status = {};
    let texts = [];
    for (const id in engine.bridges) {
        const b = engine.bridges[id];
        let s = { 'id': id, 'status': b.status, 'error': b.error || '', 'port': b.port, 'devices': Object.keys(b.endpoints).length, 'commissioned': false, 'fabrics': [], 'manual': '', 'qr': '', 'window': b.window || 0 };
        if (b.server && b.status === 'online') {
            try {
                const c = b.server.state.commissioning;
                s.commissioned = c.commissioned === true;
                s.manual = c.pairingCodes.manualPairingCode;
                s.qr = c.pairingCodes.qrPairingCode;
                s.svg = qrSvg(s.qr);
                s.fabrics = Object.values(c.fabrics || {}).map(f => ({
                    'index': Number(f.fabricIndex),
                    'vendor': Number(f.rootVendorId),
                    'label': String(f.label || '')
                }));
            } catch (e) {
                s.error = e.message;
            }
        }
        status[id] = s;
        texts.push(id + ': ' + s.status + ' (' + s.devices + ')');
    }
    global.set('matter', status, 'memoryOnly');
    node.status({
        'fill': Object.values(status).every(s => s.status === 'online') ? 'green' : 'red',
        'shape': 'dot',
        'text': texts.join(', ') || 'no bridge'
    });
    node.send([null, { 'topic': 'status' }]);
}

// matter.js binds its sockets in the background: a failure there stops Node-RED,
// so the port and IPv6 are checked before
function check(port) {
    const bind = type => new Promise(resolve => {
        const socket = dgram.createSocket({ 'type': type, 'ipv6Only': type === 'udp6' });
        socket.once('error', e => {
            try { socket.close(); } catch (e2) { }
            resolve(e.code || e.message);
        });
        socket.bind(port, () => socket.close(() => resolve('')));
    });

    return bind('udp6').then(e6 => {
        if (e6 !== '') {

            return e6 === 'EADDRINUSE' ? 'port UDP ' + port + ' déjà utilisé' : 'IPv6 indisponible (' + e6 + ')';
        }

        return bind('udp4').then(e4 => e4 === '' ? '' : (e4 === 'EADDRINUSE' ? 'port UDP ' + port + ' déjà utilisé' : 'port UDP ' + port + ' indisponible (' + e4 + ')'));
    });
}

// DKNR value to Matter attributes of a device
async function apply(bridge, id, force) {
    const item = bridge.endpoints[id];
    const dev = allDevices()[id];
    if (!item || typeof dev !== 'object' || dev === null) {

        return;
    }
    // state comes from the first entity of the device
    const uid = dev.entities[0];
    const value = valueOf(uid);
    if (value === undefined) {

        return;
    }
    const state = types[item.type].state((catalog().entities || {})[uid] || {}, value);
    if (state === null) {

        return;
    }
    const key = JSON.stringify(state);
    if (!force && item.key === key) {

        return;
    }
    item.key = key;
    await item.endpoint.set(state);
}

// order of a controller to DKNR commands, one per entity of the device
function order(bridge, id, context, asked) {
    // change written by this engine (DKNR value), not by a controller
    if (engine.closed || !context || context.offline === true) {

        return;
    }
    const item = bridge.endpoints[id];
    const dev = allDevices()[id];
    const topic = global.get('mqtt.topic', 'default') || '';
    const cfg = config();
    if (!item || typeof dev !== 'object' || dev === null || typeof types[item.type].command !== 'function') {

        return;
    }

    let out = [];
    for (const uid of dev.entities || []) {
        const value = types[item.type].command((catalog().entities || {})[uid] || {}, asked, valueOf(uid), cfg);
        if (value === undefined || topic === '') {
            continue;
        }
        out.push({
            'topic': [topic, 'set', uid].join('/'),
            'payload': String(value),
            'qos': 0,
            'retain': false
        });
    }

    // the controller already knows the asked state. If the entity does not follow,
    // its real state is written back after a delay
    item.key = JSON.stringify(asked);
    clearTimeout(item.timer);
    item.timer = setTimeout(() => {
        engine.push(() => engine.closed ? null : apply(bridge, id, true));
    }, (cfg.confirm || 10) * 1000);

    if (out.length > 0) {
        node.send([out, null]);
    }
}

// add, rename and remove the endpoints of a bridge from the devices
async function sync(bridge) {
    const list = wanted(bridge);
    let changed = false;

    for (const id in bridge.endpoints) {
        const item = bridge.endpoints[id];
        if (typeof list[id] !== 'object' || list[id].type !== item.type) {
            clearTimeout(item.timer);
            if (item.off) {
                item.off();
            }
            // delete: the endpoint number is not used again, controllers forget the device
            await item.endpoint.delete();
            delete bridge.endpoints[id];
            changed = true;
        }
    }

    for (const id in list) {
        const dev = list[id];
        const label = String(dev.name || id).slice(0, 32);
        let item = bridge.endpoints[id];
        if (!item) {
            const type = types[dev.type];
            // the endpoint id gives a stable endpoint number: changing it creates a new device on controllers
            const endpoint = new matter.Endpoint(type.device.with(behaviors.BridgedDeviceBasicInformationServer), {
                'id': id,
                'bridgedDeviceBasicInformation': {
                    'nodeLabel': label,
                    'productName': label,
                    'vendorName': 'DKNR',
                    'serialNumber': id.slice(0, 32),
                    'reachable': true
                }
            });
            await bridge.aggregator.add(endpoint);
            item = { 'endpoint': endpoint, 'type': dev.type, 'label': label, 'key': null, 'timer': null, 'off': null };
            if (typeof type.listen === 'function') {
                item.off = type.listen(endpoint, (context, asked) => order(bridge, id, context, asked));
            }
            bridge.endpoints[id] = item;
            changed = true;
        } else if (item.label !== label) {
            await item.endpoint.set({ 'bridgedDeviceBasicInformation': { 'nodeLabel': label } });
            item.label = label;
            changed = true;
        }
        await apply(bridge, id, false);
    }

    return changed;
}

async function start(id) {
    const cfg = config();
    const def = (cfg.bridges || {})[id];
    if (typeof def !== 'object' || engine.bridges[id]) {

        return;
    }
    const bridge = { 'id': id, 'port': def.port, 'status': 'starting', 'error': '', 'server': null, 'aggregator': null, 'endpoints': {}, 'offs': [], 'window': 0 };
    engine.bridges[id] = bridge;

    try {
        // previous engine (redeploy): wait for its sockets and storage to be closed
        const closing = global.get('matter_closing', 'memoryOnly');
        if (closing && typeof closing.then === 'function') {
            await closing;
        }

        const problem = await check(bridge.port);
        if (problem !== '') {
            throw new Error(problem);
        }

        // matter.js must not handle the signals nor the exit code of Node-RED
        const env = matter.Environment.default;
        env.vars.set('runtime.signals', false);
        env.vars.set('runtime.exitcode', false);
        env.vars.set('storage.path', cfg.storage);
        env.vars.set('log.level', cfg.log || 'notice');
        env.vars.set('log.format', 'plain');
        if (cfg.interface) {
            env.vars.set('mdns.networkInterface', cfg.interface);
        }

        bridge.server = await matter.ServerNode.create({
            'id': id,
            'network': { 'port': bridge.port },
            'productDescription': { 'name': def.name, 'deviceType': endpoints.AggregatorEndpoint.deviceType },
            'basicInformation': {
                'vendorName': 'DKNR',
                'vendorId': matter.VendorId(cfg.vendor),
                'productName': 'DKNR Matter',
                'productId': cfg.product,
                'nodeLabel': def.name,
                'hardwareVersion': 1,
                'hardwareVersionString': '1',
                'softwareVersion': 1,
                'softwareVersionString': String(global.get('describe.app.version', 'memoryOnly') || '1')
            }
        });
        bridge.aggregator = new matter.Endpoint(endpoints.AggregatorEndpoint, { 'id': 'aggregator' });
        await bridge.server.add(bridge.aggregator);
        await sync(bridge);
        await bridge.server.start();

        const changed = () => {
            bridge.window = 0;
            publish();
        };
        const events = bridge.server.events.commissioning;
        for (const name of ['commissioned', 'decommissioned', 'fabricsChanged']) {
            events[name].on(changed);
            bridge.offs.push(() => events[name].off(changed));
        }
        bridge.status = 'online';
    } catch (e) {
        bridge.status = 'error';
        bridge.error = e && e.message ? e.message : String(e);
        node.error('matter: bridge ' + id + ': ' + bridge.error);
        if (bridge.server) {
            try { await bridge.server.close(); } catch (e2) { }
            bridge.server = null;
        }
    }
    publish();
}

async function stop(id) {
    const bridge = engine.bridges[id];
    if (!bridge) {

        return;
    }
    for (const off of bridge.offs) {
        off();
    }
    for (const eid in bridge.endpoints) {
        clearTimeout(bridge.endpoints[eid].timer);
        if (bridge.endpoints[eid].off) {
            bridge.endpoints[eid].off();
        }
    }
    if (bridge.server) {
        try { await bridge.server.close(); } catch (e) { }
    }
    delete engine.bridges[id];
}

// actions (msg.action)
engine.actions = {
    // start the bridges (boot)
    'start': async () => {
        for (const id in config().bridges || {}) {
            await start(id);
        }
    },
    // DKNR value of an entity (msg.topic = entity uid)
    'value': async msg => {
        const all = allDevices();
        for (const id in engine.bridges) {
            const bridge = engine.bridges[id];
            if (bridge.status !== 'online') {
                continue;
            }
            for (const eid in bridge.endpoints) {
                if (typeof all[eid] === 'object' && all[eid].entities[0] === msg.topic) {
                    await apply(bridge, eid, false);
                }
            }
        }
    },
    // devices changed
    'sync': async () => {
        let changed = false;
        for (const id in engine.bridges) {
            if (engine.bridges[id].status === 'online') {
                changed = await sync(engine.bridges[id]) || changed;
            }
        }
        if (changed) {
            publish();
        }
    },
    // open the pairing of a bridge already paired, for another controller (msg.bridge)
    'open': async msg => {
        const bridge = engine.bridges[msg.bridge || 'main'];
        if (!bridge || bridge.status !== 'online') {

            return;
        }
        await bridge.server.act(agent => agent.commissioning.enterCommissionableMode());
        bridge.window = Date.now() + 15 * 60000;
        publish();
    },
    // forget all the controllers of a bridge (msg.bridge): new pairing codes
    'reset': async msg => {
        const id = msg.bridge || 'main';
        const bridge = engine.bridges[id];
        if (!bridge) {

            return;
        }
        if (bridge.server) {
            await bridge.server.erase();
        }
        await stop(id);
        await start(id);
    },
    // try again a bridge in error (msg.bridge)
    'retry': async msg => {
        const id = msg.bridge || 'main';
        if (engine.bridges[id] && engine.bridges[id].status === 'online') {

            return;
        }
        await stop(id);
        await start(id);
    }
};

engine.close = function () {
    engine.closed = true;

    return engine.push(async () => {
        for (const id of Object.keys(engine.bridges)) {
            await stop(id);
        }
    });
};

context.set('engine', engine, 'memoryOnly');
node.status({ 'fill': 'grey', 'shape': 'dot', 'text': 'waiting' });

