// Pont page: state of the Matter bridge, pairing, paired controllers and DKNR sources
// output 1: state table / output 2: pairing panel / output 3: controllers table / output 4: sources table

const cfg = global.get('describe.matter', 'memoryOnly') || {};
const status = (global.get('matter', 'memoryOnly') || {}).main || { 'status': 'starting' };
const devices = global.get('devices', 'default') || {};
const catalog = global.get('catalog', 'memoryOnly') || { 'sources': {}, 'parents': {}, 'entities': {} };

// Matter vendor ids of the usual controllers
const vendors = {
    0x1217: 'Amazon Alexa',
    0x1349: 'Apple Maison',
    0x1384: 'Apple (trousseau)',
    0x6006: 'Google Home',
    0x110a: 'Samsung SmartThings',
    0x134b: 'Home Assistant'
};

const texts = {
    'starting': 'Démarrage...',
    'online': 'En ligne',
    'error': 'Erreur'
};

const time = t => new Date(t).toLocaleTimeString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris', 'hour': '2-digit', 'minute': '2-digit' });

let rows = [];
const add = (lbl, val) => {
    if (val !== undefined && val !== null && val !== '') {
        rows.push({ 'lbl': lbl, 'val': String(val) });
    }
};
const fabrics = Array.isArray(status.fabrics) ? status.fabrics : [];
const open = status.status === 'online' && (status.commissioned !== true || status.window > Date.now());

add('Etat', (texts[status.status] || status.status) + (status.error ? ' : ' + status.error : ''));
add('Port UDP', status.port);
add('Interface réseau', cfg.interface || 'toutes');
add('Appareils publiés', status.devices === undefined ? '' : status.devices + ' / ' + Object.keys(devices).length);
add('Contrôleurs appairés', status.status === 'online' ? fabrics.length : '');
add('Appairage', status.status !== 'online' ? '' : (status.commissioned !== true ? 'en attente du premier contrôleur' : (open ? 'ouvert jusqu\'à ' + time(status.window) : 'fermé')));

// manual pairing code: 0000-000-0000
const code = String(status.manual || '').replace(/^(\d{4})(\d{3})(\d{4})$/, '$1-$2-$3');

const controllers = fabrics.map(f => ({
    'name': vendors[f.vendor] || 'Fabricant 0x' + Number(f.vendor).toString(16).toUpperCase().padStart(4, '0'),
    'label': f.label || '-',
    'index': f.index
}));

// DKNR sources
let used = {};
for (const d of Object.values(devices)) {
    for (const uid of d.entities || []) {
        used[uid] = true;
    }
}
let sources = {};
for (const s in catalog.sources) {
    sources[s] = { 'source': catalog.sources[s] + (catalog.sources[s] !== s ? ' (' + s + ')' : ''), 'parents': 0, 'entities': 0, 'used': 0 };
}
for (const p in catalog.parents) {
    const s = p.split('/')[0];
    if (sources[s]) {
        sources[s].parents++;
    }
}
for (const uid in catalog.entities) {
    const s = uid.split('/')[0];
    if (sources[s]) {
        sources[s].entities++;
        if (used[uid]) {
            sources[s].used++;
        }
    }
}

return [
    { 'payload': rows },
    {
        'payload': {
            'status': status.status || 'starting',
            'open': open,
            'commissioned': status.commissioned === true,
            'svg': open ? status.svg || '' : '',
            'code': open ? code : '',
            'controllers': fabrics.length
        }
    },
    { 'payload': controllers },
    { 'payload': Object.keys(sources).sort().map(s => sources[s]) }
];

// action asked from the pairing panel: open, reset or retry

if (!['open', 'reset', 'retry'].includes(msg.topic)) {

    return;
}

return { 'action': msg.topic, 'bridge': 'main' };

// Prototype: test devices of the Pont page, before the Appareils page
// output 1: entities of the test plug / output 2: entities of the test temperature / output 3: values table

const cfg = global.get('describe.matter', 'memoryOnly') || {};
const devices = global.get('devices', 'default') || {};
const catalog = global.get('catalog', 'memoryOnly') || { 'sources': {}, 'parents': {}, 'entities': {}, 'values': {} };
const last = global.get('last', 'default') || {};

// entities usable by a device type
function options(type, current) {
    let list = [];
    for (const uid in catalog.entities) {
        const def = catalog.entities[uid];
        const ok = type === 'switch'
            ? def.type === 'binary' || (def.type === 'number' && def.unit === '%')
            : def.type === 'number' && def.unit.indexOf('°') !== -1;
        if (ok || uid === current) {
            const parent = uid.split('/').slice(0, 2).join('/');
            list.push({ 'label': (catalog.parents[parent] || parent) + ' - ' + def.name + ' (' + uid + ')', 'value': uid });
        }
    }
    // entity not received yet (source stopped, MQTT not configured)
    if (current !== '' && typeof catalog.entities[current] !== 'object') {
        list.push({ 'label': current, 'value': current });
    }
    list.sort((a, b) => a.label.localeCompare(b.label));
    list.unshift({ 'label': 'Aucune', 'value': '' });

    return list;
}

let out = [];
let rows = [];
for (const id in cfg.tests || {}) {
    const d = devices[id];
    const current = typeof d === 'object' && Array.isArray(d.entities) && d.entities.length > 0 ? d.entities[0] : '';
    out.push({ 'payload': current, 'ui_update': { 'options': options(cfg.tests[id].type, current) } });
    if (current !== '') {
        const value = catalog.values[current] !== undefined ? catalog.values[current] : last[current];
        const unit = (catalog.entities[current] || {}).unit || '';
        rows.push({ 'lbl': cfg.tests[id].name, 'val': value === undefined ? 'aucune valeur reçue' : String(value) + (unit && unit !== 'rb' ? ' ' + unit : '') });
    }
}
out.push({ 'payload': rows });

return out;

// Prototype: entity chosen for a test device (topic = device id, payload = entity uid, empty to remove the device)
// devices have the same format as dknr-alexa: { id, name, room, type, entities, active }
// output 1: devices changed (custom - matter) / output 2: refresh of the page

const cfg = global.get('describe.matter', 'memoryOnly') || {};
const test = (cfg.tests || {})[msg.topic];

if (typeof test !== 'object') {

    return;
}

let devices = global.get('devices', 'default') || {};
const uid = typeof msg.payload === 'string' ? msg.payload : '';

if (uid === '') {
    delete devices[msg.topic];
} else {
    devices[msg.topic] = {
        'id': msg.topic,
        'name': test.name,
        'room': '',
        'type': test.type,
        'entities': [uid],
        'active': true
    };
}
global.set('devices', devices, 'default');

return [{ 'action': 'sync' }, { 'topic': 'devices' }];
